(() => {
  'use strict';
  const D = window.HayatData, KEY = 'hayat-mvp-v1';
  let storageAvailable = true, state;
  try { const saved = JSON.parse(localStorage.getItem(KEY)); state = saved?.version === D.version ? {...D.seed(), ...saved.data} : D.seed(); } catch { state = D.seed(); storageAvailable = false; }
  let route = location.hash.slice(1) || 'dashboard', filters = {query:'',blood:'',city:'',status:'all'}, modalFocus = null, pendingRequestId = null, publicView = 'landing';
  const $ = (s, root = document) => root.querySelector(s);
  const escape = (v = '') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const number = v => new Intl.NumberFormat('ar-EG').format(v);
  const formatDate = v => v ? new Intl.DateTimeFormat('ar-EG', {day:'numeric',month:'long',year:'numeric'}).format(new Date(v + 'T12:00:00')) : 'غير محدد';
  const uid = (prefix='id') => prefix + '-' + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
  const paths = {home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',drop:'M12 3C9 8 5 11 5 15a7 7 0 0 0 14 0c0-4-4-7-7-12Z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Zm3 10h2m4 0h2m-8 4h2',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',mapPin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',building:'M4 21V4h12v17M2 21h20M16 10h4v11M8 8h4M8 12h4M8 16h4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',chevron:'m14 7-5 5 5 5',arrow:'M20 12H4m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Zm4-3.9a4 4 0 0 1 0 7.8',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',chart:'M3 3v18h18M7 16v-5m5 5V7m5 9V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',shield:'m12 3 9 4v5c0 6-9 10-9 10S3 18 3 12V7Zm-4 9 3 3 5-6',logout:'M9 21H3V3h6m6 5 5 4-5 4m-9-4h14',menu:'M3 6h18M3 12h18M3 18h18',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',mail:'M3 5h18v14H3Zm0 1 9 7 9-7',phone:'M22 16.9v3a2 2 0 0 1-2.2 2A20 20 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3l2 5-2 2a16 16 0 0 0 8 8l2-2Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',edit:'m16 3 5 5L9 20l-6 1 1-6ZM14 5l5 5',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',megaphone:'m3 9 16-6v18L3 15Zm4 7 2 6h4l-2-5M22 9v6',file:'M14 2H4v20h16V8Zm0 0v6h6M8 13h8m-8 4h5',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z'};
  const icon = (name, cls='') => `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.heart}"/></svg>`;
  const save = () => { try { localStorage.setItem(KEY,JSON.stringify({version:D.version,data:state})); } catch { storageAvailable=false; toast('تعذر الحفظ في المتصفح؛ ستبقى التغييرات خلال هذه الجلسة فقط.','error'); } };
  const notify = (title,text,route='notifications') => { state.notifications.unshift({id:uid('n'),title,text,route,type:'heart',date:D.today(),read:false}); save(); };
  const toast = (message,type='success') => { const el=document.createElement('div'); el.className=`toast ${type}`; el.setAttribute('role','status'); el.innerHTML=`${icon(type==='error'?'info':'check')}<span>${escape(message)}</span>`; $('#toast-container').append(el); setTimeout(()=>el.remove(),4500); };
  const options = (items,selected='',placeholder='') => `${placeholder?`<option value="">${placeholder}</option>`:''}${items.map(x=>`<option value="${escape(x)}" ${x===selected?'selected':''}>${escape(x)}</option>`).join('')}`;
  const center = id => state.centers.find(c=>c.id===id) || {name:'مركز غير متاح',city:'',address:''};
  const daysRemaining = () => state.profile.lastDonation ? Math.max(0,(Number(state.settings.demoIntervalDays)||90)-Math.floor((new Date(D.today()+'T12:00:00')-new Date(state.profile.lastDonation+'T12:00:00'))/86400000)) : 0;
  const empty = (title,text='',ico='search') => `<div class="empty-state"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${text}</p></div>`;
  const stat = (label,value,ico,color,foot) => `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${color}">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`;
  const titles = {dashboard:['لوحة التحكم','كل عطاء يبدأ بخطوة. تابع أثرَك وكن قريبًا ممن يحتاجك.'],requests:['طلبات التبرع','هناك من ينتظر عطائك. ابحث عن طلب وكن سببًا في الأمل.'],appointments:['مواعيدي','خطوتك القادمة لصناعة فرق، في الوقت الذي يناسبك.'],history:['سجل التبرعات','كل مرة تبرعت فيها، تركت أثرًا يستحق أن يُروى.'],campaigns:['حملات التبرع','حين نجتمع على الخير، يصبح أثرنا أكبر.'],centers:['مراكز التبرع','تعرّف على المراكز واختر الأقرب إليك.'],notifications:['الإشعارات','ابقَ على اطّلاع بالطلبات والمواعيد الجديدة.'],profile:['الملف الشخصي','معلوماتك المحدّثة تساعدنا على ربطك بالفرصة المناسبة.'],donors:['المتبرعون والمطابقة','ابحث عن المتبرعين المتاحين ونسّق الاستجابة للطلبات.'],reports:['التقارير والإحصائيات','نظرة على التبرعات والطلبات ونشاط المنصة.'],users:['إدارة المستخدمين','إدارة حسابات المستخدمين وأدوارهم وحالتهم.'],institutions:['إدارة بنوك الدم','بيانات المؤسسات المشاركة في المنصة.'],settings:['إعدادات المنصة','إعدادات النموذج التجريبي لمنصة حياة.'],help:['كيف تعمل حياة؟','خطوات بسيطة تجعل التبرع أكثر سهولة وتنظيمًا.']};
  const navLink = (r,label,ico,count='') => `<a href="#${r}" class="nav-item ${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(ico,'nav-icon')}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`;
  const logo = () => `<a href="#dashboard" class="brand" ${!state.signedIn?'data-action="back-landing"':''}><img class="brand-icon" src="assets/favicon.svg" width="44" height="44" alt=""><span><strong class="brand-name">حياة<span class="brand-en">HAYAT</span></strong><small class="brand-tagline">معًا، نمنح الحياة</small></span></a>`;
  const ctx = () => ({state,icon,escape,formatDate,number,save,render,toast,openModal,closeModal,uid,notify});
  function navigate(r) { if(location.hash.slice(1)===r){route=r;render();}else location.hash=r; }
  function render() {
    if(!state.signedIn) { publicView === 'landing' ? renderLanding() : renderAuth(publicView); return; }
    if(!titles[route]) route='dashboard';
    if((['users','institutions','settings'].includes(route)&&state.role!=='admin') || (['donors','reports'].includes(route)&&state.role==='donor')) route='dashboard';
    const unread=state.notifications.filter(n=>!n.read).length;
    const roleLabel={donor:'متبرع',bank:'مسؤول بنك الدم',admin:'مدير النظام'}[state.role];
    document.title=`${titles[route][0]} | حياة`;
    $('#app').innerHTML=`<div class="app-shell"><div class="mobile-overlay" data-action="close-menu"></div><aside class="sidebar" aria-label="القائمة الرئيسية">${logo()}<div class="nav-caption">مساحتك للعطاء</div><nav class="nav-list">${navLink('dashboard','لوحة التحكم','home')}${navLink('requests','طلبات التبرع','drop',number(state.requests.filter(r=>r.status==='open').length))}${navLink('appointments','مواعيدي','calendar')}${navLink('history','سجل التبرعات','clock')}${navLink('campaigns','حملات التبرع','megaphone')}${navLink('centers','مراكز التبرع','mapPin')}${state.role!=='donor'?`<div class="nav-caption">إدارة بنك الدم</div>${navLink('donors','المتبرعون والمطابقة','users')}${navLink('reports','التقارير','chart')}`:''}${state.role==='admin'?`${navLink('users','إدارة المستخدمين','shield')}${navLink('institutions','إدارة بنوك الدم','building')}${navLink('settings','إعدادات المنصة','settings')}`:''}<div class="nav-caption">حسابك</div>${navLink('notifications','الإشعارات','bell',unread?number(unread):'')}${navLink('profile','الملف الشخصي','user')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="note-heart">${icon('heart')}</span><strong>عطاؤك يصنع فرقًا</strong><p>القليل منك، يعني الكثير لغيرك.</p><a href="#help">تعرّف على حياة ${icon('arrow')}</a></div><a href="#profile" class="sidebar-profile"><span class="avatar">${escape(state.profile.name.trim().slice(0,1))}</span><span class="profile-info"><strong>${escape(state.profile.name)}</strong><small class="profile-role">${roleLabel} <span class="profile-dot"></span></small></span>${icon('chevron')}</a></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn menu-toggle" data-action="menu" aria-label="فتح القائمة">${icon('menu')}</button><span>حياة</span>${icon('chevron')}<strong>${titles[route][0]}</strong></div><div class="topbar-actions"><form id="global-search-form" class="global-search" data-form="search">${icon('search')}<input name="query" aria-label="ابحث عن طلب أو مركز" placeholder="ابحث عن طلب أو مركز..." value="${escape(filters.query)}"></form><span class="demo-label">نسخة تجريبية</span><a class="icon-btn top-notification" href="#notifications" aria-label="الإشعارات، ${number(unread)} غير مقروءة">${icon('bell')}${unread?'<span class="notification-dot"></span>':''}</a><a href="#profile" class="avatar small-avatar" aria-label="الملف الشخصي">${escape(state.profile.name.slice(0,1))}</a></div></header><main id="page-content" class="page-content page-enter" tabindex="-1"><div class="page-heading"><div><h1 class="page-title">${titles[route][0]}</h1><p class="page-subtitle">${titles[route][1]}</p></div><div class="heading-actions">${route==='dashboard'?`<span class="today-label">${icon('calendar')}${formatDate(D.today())}</span>`:''}${route==='requests'&&state.role!=='donor'?`<button class="btn btn-primary" data-action="new-request">${icon('plus')} طلب تبرع جديد</button>`:''}${route==='appointments'?`<button class="btn btn-primary" data-action="book">${icon('plus')} حجز موعد</button>`:''}</div></div>${renderPage()}<footer class="footer"><span>حياة © ${new Date().getFullYear()} <span class="footer-divider">·</span> كل قطرة تكتب حكاية جديدة</span><span>بيانات تجريبية <span class="footer-divider">·</span><a href="#help">عن المنصة</a></span></footer></main></div></div>`;
    if(route==='donors') $('.info-banner span').textContent='تُطابق الفصائل حسب توافق نقل خلايا الدم الحمراء وعامل Rh. المسافات والعدّاد افتراضية، والأهلية النهائية يحددها بنك الدم.';
    if(route==='help') $('.help-faq details:nth-of-type(2) p').textContent='تُعرض الطلبات المتوافقة وفق قواعد فصائل خلايا الدم الحمراء وعامل Rh، لكن هذه ليست موافقة طبية. بنك الدم وحده يحدد الأهلية النهائية بعد الفحص.';
    document.body.classList.remove('menu-open');
  }
  function renderLanding(){
    document.title='حياة | تبرّعك يصنع حياة';
    const activeRequests=state.requests.filter(r=>r.status==='open').length;
    const upcomingCampaigns=state.campaigns.filter(c=>c.date>=D.today()).length;
    $('#app').innerHTML=`<div class="landing-page">
      <header class="landing-nav">
        <a class="landing-logo" href="#top" aria-label="حياة، الصفحة الرئيسية"><img src="assets/favicon.svg" width="45" height="45" alt=""><span><strong>حياة</strong><small>معًا، نمنح الحياة</small></span></a>
        <nav class="landing-links" aria-label="روابط الصفحة"><a href="#how">كيف تعمل؟</a><a href="#impact">أثرنا</a><a href="#about">عن حياة</a></nav>
        <div class="landing-nav-actions"><button class="landing-login" data-action="open-login">تسجيل الدخول</button><button class="landing-join" data-action="open-register">انضم الآن ${icon('arrow')}</button></div>
      </header>
      <main id="page-content">
        <section class="landing-hero" id="top">
          <div class="landing-hero-copy"><span class="landing-eyebrow"><i></i> لأن كل قطرة تصنع فرقًا</span><h1>امنح من دمك،<br><em>وامنح حياة.</em></h1><p>منصة تجمع المتبرعين ببنوك الدم، وتحوّل رغبتك في العطاء إلى خطوة واضحة، قريبة، وفي الوقت المناسب.</p><div class="landing-hero-actions"><button class="landing-cta" data-action="open-register">ابدأ رحلة العطاء ${icon('arrow')}</button><a class="landing-play" href="#how"><span>${icon('drop')}</span> اكتشف كيف تعمل</a></div><div class="landing-trust"><span>${icon('shield')} بياناتك محفوظة</span><span>${icon('clock')} حجز بخطوات بسيطة</span></div></div>
          <div class="landing-visual" aria-label="رسم توضيحي للتبرع بالدم"><span class="landing-orbit orbit-one"></span><span class="landing-orbit orbit-two"></span><div class="landing-art">${heroArt()}</div><div class="floating-card request-float"><span class="float-icon">${icon('drop')}</span><div><small>طلب قريب منك</small><strong>فصيلة <bdi>A+</bdi></strong><span><i></i> حاجة عاجلة</span></div></div><div class="floating-card impact-float"><span>${icon('heart')}</span><div><strong>تبرّع واحد</strong><small>قد يساعد في إنقاذ ٣ أشخاص</small></div></div></div>
        </section>
        <section class="landing-numbers" id="impact" aria-label="أرقام المنصة"><div><strong>${number(state.centers.length)}+</strong><span>مراكز تبرع</span></div><i></i><div><strong>${number(activeRequests)}</strong><span>طلبات نشطة</span></div><i></i><div><strong>${number(upcomingCampaigns)}</strong><span>حملات قادمة</span></div><i></i><div><strong>٢٤/٧</strong><span>وصول للمنصة</span></div></section>
        <section class="landing-section how-section" id="how"><div class="landing-section-heading"><span>خطوات بسيطة، أثر كبير</span><h2>رحلتك للعطاء تبدأ من هنا</h2><p>نقرّب لك الفرصة المناسبة ونساعدك على تنظيم كل خطوة.</p></div><div class="how-grid"><article><b>٠١</b><span>${icon('user')}</span><h3>أنشئ ملفك</h3><p>سجّل فصيلة دمك ومدينتك لتصل إليك الفرص الأقرب والأنسب.</p></article><article><b>٠٢</b><span>${icon('search')}</span><h3>اختر فرصة</h3><p>استكشف الطلبات والحملات، واعرف أين يكون عطاؤك أكثر حاجة.</p></article><article><b>٠٣</b><span>${icon('calendar')}</span><h3>احجز موعدك</h3><p>اختر المركز والوقت المناسبين لك، وتابع موعدك من مكان واحد.</p></article></div></section>
        <section class="landing-story" id="about"><div class="story-visual"><span class="story-drop">${icon('drop')}</span><div><strong>كل ٢ ثانية</strong><p>يحتاج شخص ما إلى الدم حول العالم.</p></div><span class="story-ring ring-a"></span><span class="story-ring ring-b"></span></div><div class="story-copy"><span class="landing-eyebrow"><i></i> وقتك يصنع أملًا</span><h2>بين الرغبة في العطاء<br>ومن ينتظرها... <em>حياة.</em></h2><p>نبني جسرًا إنسانيًا ذكيًا بين المتبرعين ومراكز الدم؛ لتصبح الاستجابة للاحتياج أسرع، والتجربة أوضح، والأثر أقرب.</p><ul><li>${icon('check')} طلبات واضحة ومحدّثة</li><li>${icon('check')} مراكز وحملات في مكان واحد</li><li>${icon('check')} سجل يحفظ رحلة عطائك</li></ul><button class="landing-text-cta" data-action="open-register">كن جزءًا من الحكاية ${icon('arrow')}</button></div></section>
        <section class="landing-final"><span>${icon('heart')}</span><h2>قطرة منك، حياة كاملة لغيرك.</h2><p>انضم إلى مجتمع يؤمن أن أجمل أثر هو الذي يبقى في حياة إنسان.</p><button class="landing-cta light" data-action="open-register">أنشئ حسابك مجانًا ${icon('arrow')}</button></section>
      </main>
      <footer class="landing-footer"><a class="landing-logo" href="#top"><img src="assets/favicon.svg" width="38" height="38" alt=""><span><strong>حياة</strong><small>معًا، نمنح الحياة</small></span></a><p>منصة تجريبية للتنسيق والتبرع بالدم.</p><span>© ${new Date().getFullYear()} حياة</span></footer>
    </div>`;
  }
  function renderPage(){
    const admin=window.HayatAdmin?.render(route,ctx()); if(admin!=null)return admin;
    return ({dashboard:dashboard,requests:requestsPage,appointments:appointmentsPage,history:historyPage,campaigns:campaignsPage,centers:centersPage,notifications:notificationsPage,profile:profilePage,help:helpPage}[route]||dashboard)();
  }
  function dashboard(){
    if(state.role!=='donor')return managementDashboard();
    const open=state.requests.filter(r=>r.status==='open'), upcoming=state.appointments.filter(a=>a.status==='confirmed'&&a.date>=D.today()).sort((a,b)=>a.date.localeCompare(b.date))[0];
    const n=state.history.length, remaining=daysRemaining();
    return `<section class="welcome-banner"><div class="welcome-copy"><div class="welcome-kicker"><span class="live-dot"></span> العطاء يبدأ منك</div><h2 class="welcome-title">أهلًا ${escape(state.profile.name.split(' ')[0])}،<br>وجودك يمنح <span>الحياة.</span></h2><p class="welcome-text">قد تكون قطرة دم منك بدايةً جديدة لشخص آخر.<br>خطوة بسيطة منك، وأثر لا يُنسى.</p><div class="welcome-actions"><button class="btn btn-primary" data-action="book">${icon('drop')} احجز موعدًا للتبرع ${icon('arrow')}</button><a class="btn btn-ghost" href="#requests">استكشف الطلبات</a></div></div><div class="hero-art">${heroArt()}<div class="hero-badge">${icon('shield')} معًا، نبض واحد وحياة أكثر</div></div></section><section class="stats-grid" aria-label="ملخص نشاط المنصة">${stat('تبرعاتك السابقة',number(n),'drop','red','<span class="trend">'+icon('heart')+' شكرًا لكل مرة أعطيت فيها</span>')}${stat('طلبات بانتظار العطاء',number(open.length),'heart','amber',`${number(open.filter(r=>r.urgency==='urgent').length)} طلبات ذات أولوية عاجلة`)}${stat('مراكز التبرع',number(state.centers.length),'building','blue','مراكز مشاركة في النسخة التجريبية')}${stat('حملات قادمة',number(state.campaigns.filter(c=>c.date>=D.today()).length),'users','green','فرص جديدة لصناعة أثر معًا')}</section><div class="dashboard-columns"><div class="dashboard-main"><section class="panel requests-panel"><div class="panel-header"><div><h2 class="panel-title">هناك من يحتاجك <span class="live-dot red-dot"></span></h2><p class="panel-subtitle">طلبات تبرع تستحق لحظة من وقتك</p></div><a class="text-link" href="#requests">جميع الطلبات ${icon('arrow')}</a></div><div class="requests-grid">${open.slice(0,4).map(requestCard).join('')}</div></section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">العطاء أجمل معًا</h2><p class="panel-subtitle">شارك في حملات التبرع القادمة</p></div><a href="#campaigns" class="text-link">كل الحملات ${icon('arrow')}</a></div>${campaignCard(state.campaigns[0],true)}</section></div><aside class="dashboard-aside"><section class="panel journey-card"><div class="panel-header"><h2 class="panel-title">رحلتك في العطاء</h2>${icon('heart')}</div><div class="donor-ring"><svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="67" fill="none" stroke="#f4e9eb" stroke-width="9"/><circle cx="80" cy="80" r="67" fill="none" stroke="#df3e4f" stroke-width="9" stroke-linecap="round" stroke-dasharray="${Math.min(n/5,1)*421} 421" transform="rotate(-90 80 80)"/></svg><div><span class="ring-drop">${icon('drop')}</span><strong>${number(n)}</strong><small>تبرعات مليئة بالأمل</small></div></div><div class="journey-stats"><div class="journey-stat"><strong class="ltr">${escape(state.profile.bloodType)}</strong><span>فصيلة دمك</span></div><div class="journey-stat"><strong>${escape(state.profile.city)}</strong><span>مدينتك</span></div></div><div class="eligibility-note ${remaining?'waiting':''}">${icon(remaining?'clock':'check')}<div><strong>${remaining?`${number(remaining)} يومًا حسب عدّاد العرض`:'يمكنك إبداء رغبتك بالتبرع'}</strong><small>الأهلية النهائية يحددها بنك الدم. العدّاد تجريبي.</small></div></div><a class="text-link centered-link" href="#history">شاهد سجل عطائك ${icon('arrow')}</a></section><section class="panel"><div class="panel-header"><h2 class="panel-title">موعدك القادم</h2>${icon('calendar')}</div>${upcoming?`<div class="appointment-mini"><div class="appointment-date"><strong>${number(new Date(upcoming.date+'T12:00:00').getDate())}</strong><span>${new Intl.DateTimeFormat('ar-EG',{month:'short'}).format(new Date(upcoming.date+'T12:00:00'))}</span></div><div><strong>${escape(center(upcoming.centerId).name)}</strong><p>${icon('clock')} <bdi>${upcoming.time}</bdi> صباحًا</p><span class="badge success">موعد مؤكد</span></div></div><a href="#appointments" class="btn btn-secondary full-width">تفاصيل الموعد ${icon('arrow')}</a>`:empty('موعدك القادم يبدأ هنا','اختر مركزًا ووقتًا مناسبًا لك.','calendar')}</section><section class="kind-note"><span class="kind-quote">“</span><p>يمكن أن تنسى يوم تبرعك،<br>لكن هناك من سيبقى يتذكر<br><strong>أنه حصل على فرصة أخرى.</strong></p><span>كن أنت تلك الفرصة ${icon('heart')}</span></section></aside></div>`;
  }
  function managementDashboard(){const active=state.requests.filter(r=>r.status==='open'),completed=state.requests.filter(r=>r.status==='completed'),available=state.donors.filter(d=>d.available&&d.status!=='suspended');return `<section class="management-welcome panel"><div><span class="eyebrow">${state.role==='admin'?'إدارة المنصة':'مساحة بنك الدم'}</span><h2>تنسيق أفضل، فرصة حياة أكبر.</h2><p class="muted">تابع الاحتياجات، وصِل الطلبات بالمتبرعين، واجعل كل استجابة أقرب إلى أثر.</p></div><button class="btn btn-primary" data-action="new-request">${icon('plus')} إنشاء طلب تبرع</button></section><section class="stats-grid">${stat('طلبات نشطة',number(active.length),'drop','red',`${number(active.filter(r=>r.urgency==='urgent').length)} منها عاجلة`)}${stat('طلبات مكتملة',number(completed.length),'check','green','وفق الحالات المسجلة')}${stat('متبرعون متاحون',number(available.length),'users','blue','حسابات العرض النشطة')}${stat('مراكز مشاركة',number(state.centers.length),'building','amber','ضمن دليل المنصة')}</section><div class="management-shortcuts"><a class="panel" href="#donors">${icon('users')}<div><strong>مطابقة المتبرعين</strong><span>ابحث بالفصيلة والمدينة والنطاق</span></div>${icon('arrow')}</a><a class="panel" href="#reports">${icon('chart')}<div><strong>التقارير والإحصائيات</strong><span>راجع النشاط ونزّل التقرير</span></div>${icon('arrow')}</a>${state.role==='admin'?`<a class="panel" href="#users">${icon('shield')}<div><strong>إدارة المستخدمين</strong><span>الحسابات والأدوار والحالات</span></div>${icon('arrow')}</a>`:''}</div><section class="requests-panel panel"><div class="panel-header"><div><h2 class="panel-title">الطلبات التي تحتاج متابعة</h2><p class="panel-subtitle">آخر الاحتياجات المسجلة في المنصة</p></div><a href="#requests" class="text-link">جميع الطلبات ${icon('arrow')}</a></div><div class="requests-grid full-requests">${active.length?active.map(requestCard).join(''):empty('لا توجد طلبات نشطة','يمكنك إنشاء طلب جديد عند الحاجة.','check')}</div></section>`;}
  function heroArt(){ return `<svg viewBox="0 0 410 255" fill="none" role="img" aria-label="رسم توضيحي لكيس تبرع بالدم وقلب"><circle cx="210" cy="130" r="108" fill="#F7DDE1"/><circle cx="210" cy="130" r="86" stroke="#EFC6CE" stroke-dasharray="4 8"/><path d="M88 206c36-19 42-50 35-83-29 14-42 42-35 83Z" fill="#98AF9C"/><path d="M82 218c-27-6-45-32-43-62 31 3 47 29 43 62Z" fill="#C0CEC0"/><path d="M82 232c10-28 17-55 23-84" stroke="#77967B" stroke-width="3" stroke-linecap="round"/><ellipse cx="216" cy="230" rx="105" ry="10" fill="#EDCDD2"/><g transform="rotate(-8 213 115)"><rect x="157" y="39" width="121" height="159" rx="23" fill="white" stroke="#E5B9C2" stroke-width="2"/><path d="M161 112c38 13 66-12 113 0v59c0 13-10 23-23 23h-67c-13 0-23-10-23-23Z" fill="#DF3E4F"/><path d="M161 126c45 8 71-9 113 0v45c0 13-10 23-23 23h-67c-13 0-23-10-23-23Z" fill="#CA3045"/><rect x="199" y="28" width="35" height="18" rx="5" fill="#FDF6F7" stroke="#E5B9C2" stroke-width="2"/><path d="M215 29V18" stroke="#CA939E" stroke-width="4" stroke-linecap="round"/><rect x="180" y="68" width="75" height="57" rx="9" fill="#FFF8F8"/><path d="M217 78v28m-14-14h28" stroke="#DF3E4F" stroke-width="8" stroke-linecap="round"/><path d="M209 198v19c0 10 14 14 23 6l32-28" stroke="#CA939E" stroke-width="5" stroke-linecap="round"/><path d="M174 58v26" stroke="white" stroke-width="5" stroke-linecap="round"/></g><g transform="rotate(10 309 172)"><rect x="269" y="133" width="81" height="72" rx="20" fill="white"/><path d="M309 187s-26-16-23-30c3-12 17-13 23-3 6-10 20-9 23 3 3 14-23 30-23 30Z" fill="#E77382"/></g><circle cx="119" cy="66" r="24" fill="white"/><path d="M119 52c-5 8-11 12-11 18a11 11 0 0 0 22 0c0-6-6-10-11-18Z" fill="#DF3E4F"/><path d="M302 43v16m-8-8h16M67 119v10m-5-5h10" stroke="#D998A4" stroke-width="3" stroke-linecap="round"/><circle cx="343" cy="98" r="5" fill="#DFA1AC"/><circle cx="148" cy="217" r="4" fill="#DFA1AC"/></svg>`; }
  function requestCard(r){
    const response=state.responses.find(s=>s.requestId===r.id), status=r.status==='completed'?'<span class="badge success">مكتمل</span>':r.status==='cancelled'?'<span class="badge muted">ملغي</span>':`<span class="badge ${r.urgency==='urgent'?'urgent':'normal'}">${r.urgency==='urgent'?'<span class="live-dot red-dot"></span> حاجة عاجلة':'طلب تبرع'}</span>`;
    return `<article class="request-card"><div class="request-card-top"><span class="blood-type" dir="ltr">${escape(r.bloodType)}</span>${status}<span class="request-time">${r.created===D.today()?'اليوم':formatDate(r.created)}</span></div><h3 class="request-hospital">${escape(r.hospital)}</h3><div class="request-location">${icon('mapPin')} ${escape(r.city)} <span>· بنك دم مشارك</span></div><div class="request-progress"><span><strong>${number(r.fulfilled)}</strong> من ${number(r.units)} وحدات مكتملة</span><span>${number(Math.round(r.fulfilled/r.units*100))}٪</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(r.fulfilled/r.units*100,100)}%"></div></div><div class="request-card-footer"><span class="small muted">${response?response.status==='accepted'?'✓ أبديت رغبتك بالتبرع':'اعتذرت عن هذا الطلب':`${number(r.responses)} متطوعًا استجابوا`}</span><button class="btn ${r.status==='open'?'btn-soft':'btn-ghost'} btn-sm" data-action="request-detail" data-id="${escape(r.id)}">${r.status==='open'?'عرض الطلب':'التفاصيل'} ${icon('arrow')}</button></div></article>`;
  }
  function requestsPage(){ return `<div class="filter-bar"><div class="filter-tabs" role="group" aria-label="حالة الطلبات">${[['all','جميع الطلبات'],['urgent','العاجلة'],['matching','تناسب فصيلتي'],['responded','استجبت لها']].map(([id,t])=>`<button class="filter-tab ${filters.status===id?'active':''}" data-action="filter-status" data-value="${id}" aria-pressed="${filters.status===id}">${t}</button>`).join('')}</div><div class="filters"><label class="search-field">${icon('search')}<input class="input" id="request-search" placeholder="ابحث باسم المركز أو المدينة" aria-label="البحث في الطلبات" value="${escape(filters.query)}"></label><select class="select" id="blood-filter" aria-label="تصفية حسب فصيلة الدم">${options(D.bloodTypes,filters.blood,'جميع الفصائل')}</select><select class="select" id="city-filter" aria-label="تصفية حسب المدينة">${options(D.cities,filters.city,'جميع المدن')}</select></div></div><div class="results-caption" id="request-count"></div><div class="requests-grid full-requests" id="request-results">${filteredRequests()}</div>`; }
  function filteredRequests(){const q=filters.query.trim().toLowerCase(); const rows=state.requests.filter(r=>(!q||(r.hospital+' '+r.city+' '+r.bloodType).toLowerCase().includes(q))&&(!filters.blood||r.bloodType===filters.blood)&&(!filters.city||r.city===filters.city)&&(filters.status==='all'||filters.status==='urgent'&&r.urgency==='urgent'&&r.status==='open'||filters.status==='matching'&&D.canDonate(state.profile.bloodType,r.bloodType)&&r.status==='open'||filters.status==='responded'&&state.responses.some(s=>s.requestId===r.id)));return rows.length?rows.map(requestCard).join(''):empty('لم نجد طلبات بهذه الخيارات','جرّب تغيير الفصيلة أو المدينة أو عبارة البحث.');}
  function campaignCard(c,compact=false){return `<article class="campaign-card ${compact?'campaign-compact':''}"><div class="campaign-art ${escape(c.theme)}"><span class="campaign-art-dots"></span>${icon('drop')}<strong>${escape(c.title)}</strong><small>لأن العطاء يجمعنا</small></div><div class="campaign-content"><span class="badge ${c.joined?'success':'normal'}">${c.joined?'أنت مشارك في الحملة':'حملة قادمة'}</span><h3 class="campaign-title">${escape(c.subtitle)}</h3><p class="campaign-meta">${icon('mapPin')}${escape(c.location)}</p><p class="campaign-meta">${icon('calendar')}${formatDate(c.date)} <span>· ${c.time}</span></p><div class="campaign-footer"><span>${icon('users')} ${number(c.enrolled)} مشاركًا</span><button class="btn ${c.joined?'btn-secondary':'btn-primary'} btn-sm" data-action="join-campaign" data-id="${c.id}">${c.joined?'إلغاء المشاركة':'شارك في الحملة'} ${icon(c.joined?'close':'arrow')}</button></div></div></article>`;}
  function campaignsPage(){return `<div class="info-banner">${icon('heart')}<span>فرص للعطاء مع مجتمعك. المشاركة هنا تجريبية ولا ترسل تسجيلًا إلى أي جهة.</span></div><div class="campaigns-grid">${state.campaigns.map(c=>campaignCard(c)).join('')}</div>`;}
  function appointmentsPage(){const rows=[...state.appointments].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="info-banner">${icon('info')}<span>المواعيد محاكاة محلية؛ لم يتم إرسال حجز إلى مركز فعلي.</span></div><div class="list-stack">${rows.length?rows.map(a=>`<article class="panel appointment-row"><div class="appointment-date"><strong>${number(new Date(a.date+'T12:00:00').getDate())}</strong><span>${new Intl.DateTimeFormat('ar-EG',{month:'short'}).format(new Date(a.date+'T12:00:00'))}</span></div><div class="appointment-row-info"><h3>${escape(center(a.centerId).name)}</h3><p>${icon('mapPin')}${escape(center(a.centerId).city)} <span>·</span> ${formatDate(a.date)} <span>·</span> <bdi>${a.time}</bdi></p><span class="small muted" dir="ltr">${escape(a.id)}</span></div><span class="badge ${a.status==='confirmed'?'success':a.status==='completed'?'info':'muted'}">${a.status==='confirmed'?(a.date<D.today()?'بانتظار تحديث المركز':'مؤكد'):a.status==='completed'?'تم التبرع':'ملغي'}</span><div class="table-actions">${a.status==='confirmed'?`<button class="btn btn-secondary btn-sm" data-action="reschedule" data-id="${a.id}">تعديل الموعد</button><button class="btn btn-ghost btn-sm danger-text" data-action="cancel-appointment" data-id="${a.id}">إلغاء</button>${state.role!=='donor'?`<button class="btn btn-primary btn-sm" data-action="complete-donation" data-id="${a.id}">تسجيل التبرع</button>`:''}`:''}</div></article>`).join(''):empty('لا توجد مواعيد بعد','اضغط «حجز موعد» لبدء رحلتك في العطاء.','calendar')}</div>`;}
  function historyPage(){return `<div class="stats-grid history-stats">${stat('إجمالي تبرعاتك',number(state.history.length),'drop','red','كل تبرع يترك أثرًا')}${stat('آخر تبرع',state.profile.lastDonation?formatDate(state.profile.lastDonation):'لم تتبرع بعد','calendar','blue','وفق البيانات المحفوظة في حسابك')}${stat('الفصيلة المسجلة',`<bdi>${escape(state.profile.bloodType)}</bdi>`,'heart','green','يمكن تعديلها من الملف الشخصي')}</div><section class="panel"><div class="panel-header"><h2 class="panel-title">سجل العطاء</h2><button class="btn btn-secondary btn-sm" data-action="export-history">${icon('download')} تنزيل السجل</button></div><div class="table-wrap"><table><thead><tr><th>رقم التبرع</th><th>المركز</th><th>التاريخ</th><th>الفصيلة</th><th>الحالة</th></tr></thead><tbody>${state.history.map(h=>`<tr><td><bdi>${escape(h.id)}</bdi></td><td>${escape(center(h.centerId).name)}</td><td>${formatDate(h.date)}</td><td><span class="blood-chip" dir="ltr">${escape(h.bloodType)}</span></td><td><span class="badge success">تم التبرع</span></td></tr>`).join('')}</tbody></table>${!state.history.length?empty('لم يبدأ سجلّك بعد','سيظهر هنا كل تبرع يسجله مسؤول بنك الدم.','heart'):''}</div></section>`;}
  function centersPage(){return `<div class="info-banner">${icon('mapPin')}<span>دليل توضيحي لمراكز قطاع غزة؛ المواقع وساعات العمل أدناه بيانات عرض غير معتمدة.</span></div><div class="center-map"><div class="map-grid"></div><div class="map-road road-one"></div><div class="map-road road-two"></div><span class="map-water-label">البحر المتوسط</span><span class="map-city city-one">غزة</span><span class="map-city city-two">دير البلح</span><span class="map-city city-three">خان يونس</span>${state.centers.map(c=>`<button class="map-marker" style="left:${c.x||50}%;top:${c.y||50}%" data-action="center-detail" data-id="${c.id}" aria-label="${escape(c.name)}">${icon('drop')}</button>`).join('')}<span class="map-caption">مخطط توضيحي · ليس خريطة ملاحة</span></div><div class="content-grid centers-grid">${state.centers.map(c=>`<article class="panel center-card"><div class="center-icon">${icon('building')}</div><h3>${escape(c.name)}</h3><p>${icon('mapPin')}${escape(c.city)} · ${escape(c.address)}</p><p>${icon('clock')}${escape(c.hours||'تواصل مع المركز لتحديد الموعد')}</p><div class="center-card-actions"><button class="btn btn-primary btn-sm" data-action="book" data-center="${c.id}">احجز موعدًا ${icon('arrow')}</button><button class="btn btn-ghost btn-sm" data-action="center-detail" data-id="${c.id}">التفاصيل</button></div></article>`).join('')}</div>`;}
  function notificationsPage(){return `<section class="panel"><div class="panel-header"><h2 class="panel-title">آخر التحديثات <span class="badge normal">${number(state.notifications.filter(n=>!n.read).length)} جديدة</span></h2><button class="btn btn-secondary btn-sm" data-action="read-all">${icon('check')} تحديد الكل كمقروء</button></div>${state.notifications.length?state.notifications.map(n=>`<button class="notification-item ${n.read?'':'unread'}" data-action="notification" data-id="${escape(n.id)}"><span class="notification-icon ${n.type==='urgent'?'red':''}">${icon(n.type==='urgent'?'drop':n.type)}</span><span class="notification-content"><strong>${escape(n.title)}</strong><span>${escape(n.text)}</span><small class="notification-time">${formatDate(n.date)}</small></span>${!n.read?'<span class="live-dot red-dot"></span>':icon('chevron')}</button>`).join(''):empty('كل شيء هادئ هنا','ستجد هنا إشعارات الطلبات والمواعيد.','bell')}</section>`;}
  function profilePage(){const p=state.profile;return `<div class="profile-layout"><aside class="panel profile-card"><span class="profile-avatar">${escape(p.name.slice(0,1))}</span><h2 class="profile-name">${escape(p.name)}</h2><p class="muted">${escape(p.email)}</p><span class="blood-type" dir="ltr">${escape(p.bloodType)}</span><div class="detail-list"><div class="detail-row"><span>المدينة</span><strong>${escape(p.city)}</strong></div><div class="detail-row"><span>التبرعات</span><strong>${number(state.history.length)}</strong></div><div class="detail-row"><span>نوع الحساب</span><strong>${{donor:'متبرع',bank:'بنك دم',admin:'مدير النظام'}[state.role]}</strong></div></div><button class="btn btn-secondary full-width" data-action="logout">${icon('logout')} تسجيل الخروج</button></aside><div><form class="panel settings-card" data-form="profile"><div class="panel-header"><h2 class="panel-title">معلوماتك الشخصية</h2>${icon('user')}</div><div class="panel-body"><div class="form-grid">${field('الاسم الكامل','name',p.name,'text','required minlength="3" maxlength="70"')}${field('البريد الإلكتروني','email',p.email,'email','required')}${field('رقم الجوال','phone',p.phone,'tel','required pattern="[+0-9 ()-]{7,20}"')}${field('تاريخ الميلاد','birthDate',p.birthDate,'date',`required max="${D.today()}"`)}<label class="field"><span class="field-label">فصيلة الدم</span><select name="bloodType" class="select" required>${options([...D.bloodTypes,'غير معروف'],p.bloodType)}</select></label><label class="field"><span class="field-label">المدينة</span><select name="city" class="select" required>${options(D.cities,p.city)}</select></label>${field('تاريخ آخر تبرع (اختياري)','lastDonation',p.lastDonation,'date',`max="${D.today()}"`)}</div><p class="form-hint">العدّاد مبني على فترة عرض تجريبية مقدارها ${number(state.settings.demoIntervalDays||90)} يومًا. لا يمثل تقييمًا طبيًا لأهلية التبرع.</p><div class="preference-row"><div><strong>متاح لتلقي طلبات التبرع</strong><p>إظهارك ضمن نتائج البحث التجريبية للمتبرعين.</p></div><label class="switch"><input type="checkbox" name="available" ${p.available?'checked':''} aria-label="متاح لتلقي طلبات التبرع"><span></span></label></div><div class="preference-row"><div><strong>تنبيهات الطلبات العاجلة</strong><p>إضافة تنبيه محلي عند وجود طلب مطابق لفصيلتك.</p></div><label class="switch"><input type="checkbox" name="emergencyAlerts" ${p.emergencyAlerts?'checked':''} aria-label="تنبيهات الطلبات العاجلة"><span></span></label></div><div class="preference-row"><div><strong>تذكيرات المواعيد</strong><p>إضافة إشعار تأكيد محلي عند حجز موعد أو تعديله.</p></div><label class="switch"><input type="checkbox" name="reminders" ${p.reminders?'checked':''} aria-label="تذكيرات المواعيد"><span></span></label></div><button class="btn btn-primary" type="submit">${icon('check')} حفظ التغييرات</button></div></form><section class="panel settings-card"><div class="panel-header"><h2 class="panel-title">جرّب أدوار المنصة</h2><span class="badge normal">للعرض فقط</span></div><div class="panel-body"><p class="muted">انتقل بين تجارب المشروع. هذه محاكاة أدوار، وليست مصادقة أو صلاحيات آمنة.</p><label class="field"><span class="field-label">الدور الحالي</span><select class="select" id="role-selector">${[['donor','متبرع'],['bank','مسؤول بنك الدم'],['admin','مدير النظام']].map(([v,t])=>`<option value="${v}" ${state.role===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn btn-ghost danger-text" data-action="reset">إعادة ضبط البيانات التجريبية</button></div></section></div></div>`;}
  function field(label,name,value='',type='text',attrs=''){return `<label class="field"><span class="field-label">${label}</span><input class="input" name="${name}" type="${type}" value="${escape(value||'')}" ${attrs}></label>`;}
  function helpPage(){return `<div class="help-hero">${icon('heart')}<h2>بخطوة منك، تستمر الحياة.</h2><p>حياة مشروع لتنسيق التبرع بالدم في قطاع غزة، يجمع المتبرعين وبنوك الدم في مكان واحد.</p></div><div class="help-grid">${[['user','١. أكمل معلوماتك','أضف فصيلة دمك ومدينتك وحدّث آخر تاريخ للتبرع.'],['search','٢. اكتشف الطلبات','ابحث عن الطلبات المناسبة وتعرّف على المراكز المشاركة.'],['calendar','٣. أبدِ رغبتك واحجز','استجب للطلب واختر موعدًا مناسبًا، ثم تابع حالته من حسابك.']].map(([i,t,d])=>`<article class="panel help-step">${icon(i)}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div><section class="panel help-faq"><h2>أسئلة شائعة</h2><details open><summary>هل هذه النسخة متصلة ببنوك دم حقيقية؟</summary><p>هذه نسخة فرونت إند لمشروع التخرج. جميع الحسابات والطلبات والمواعيد والإشعارات تجريبية ومحفوظة في متصفحك فقط. لا تُرسل رسائل SMS أو حجوزات فعلية.</p></details><details><summary>كيف تُحدَّد أهليتي للتبرع؟</summary><p>العدّاد في هذه النسخة توضيحي وقابل للتعديل، وليس إرشادًا طبيًا. بنك الدم هو المسؤول عن تحديد الأهلية والفحوصات. المطابقة المعروضة تعتمد الفصيلة نفسها وموقعًا تجريبيًا، ولا تمثل توافقًا طبيًا.</p></details><details><summary>كيف أجرّب دور مسؤول بنك الدم أو المدير؟</summary><p>من الملف الشخصي، اختر الدور في قسم «جرّب أدوار المنصة». ستظهر إدارة الطلبات والمطابقة والتقارير، وللمدير إدارة المستخدمين والمؤسسات.</p></details><details><summary>هل تبقى التغييرات بعد إغلاق الصفحة؟</summary><p>نعم، عند سماح المتصفح بالتخزين المحلي. يمكنك إعادة ضبط جميع البيانات التجريبية من الملف الشخصي. لا تستخدم بيانات شخصية حقيقية في هذا النموذج.</p></details></section>`;}
  function openModal(title,body,footer='',wide=false){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 class="modal-title" id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="إغلاق">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('.modal input:not([type=hidden]), .modal select, .modal button')?.focus(),30);}
  function closeModal(){ $('#modal-root').innerHTML='';document.body.classList.remove('modal-open');if(modalFocus?.isConnected)modalFocus.focus(); }
  function confirmDialog(title,text,action,id='',label='تأكيد'){openModal(title,`<p class="modal-description">${text}</p>`,`<button class="btn btn-secondary" data-action="close-modal">تراجع</button><button class="btn btn-primary" data-action="${action}" data-id="${escape(id)}">${label}</button>`);}
  function requestDetail(id){const r=state.requests.find(r=>r.id===id);if(!r)return;const response=state.responses.find(s=>s.requestId===id);openModal('تفاصيل طلب التبرع',`<div class="request-detail-hero"><span class="blood-type" dir="ltr">${escape(r.bloodType)}</span><div><h3>${escape(r.hospital)}</h3><p class="muted">${icon('mapPin')} ${escape(r.city)} <span class="small">· ${escape(r.id)}</span></p></div><span class="badge ${r.urgency==='urgent'?'urgent':'normal'}">${r.urgency==='urgent'?'عاجل':'عادي'}</span></div><div class="detail-list"><div class="detail-row"><span>الوحدات المطلوبة</span><strong>${number(r.units)}</strong></div><div class="detail-row"><span>الوحدات المكتملة</span><strong>${number(r.fulfilled)}</strong></div><div class="detail-row"><span>نطاق البحث</span><strong>${number(r.radius||15)} كم (تجريبي)</strong></div><div class="detail-row"><span>الحالة</span><strong>${r.status==='open'?'نشط':r.status==='completed'?'مكتمل':'ملغي'}</strong></div></div><p class="modal-description">${escape(r.note)}</p>${response?`<div class="info-banner">${icon('info')} ${response.status==='accepted'?'أبديت رغبتك بالتبرع لهذا الطلب.':'اعتذرت عن هذا الطلب. يمكنك تغيير استجابتك ما دام الطلب نشطًا.'}</div>`:''}<p class="form-hint">المعلومات تجريبية. يحدد بنك الدم ملاءمة التبرع طبيًا.</p>`,r.status==='open'?(state.role==='donor'?`<button class="btn btn-secondary" data-action="decline-request" data-id="${id}">لا أستطيع الآن</button><button class="btn btn-primary" data-action="accept-request" data-id="${id}">${icon('heart')} ${response?.status==='accepted'?'احجز موعدًا':'أستطيع التبرع'}</button>`:`<button class="btn btn-ghost danger-text" data-action="cancel-request" data-id="${id}">إلغاء الطلب</button><button class="btn btn-secondary" data-action="edit-request" data-id="${id}">تعديل</button><button class="btn btn-secondary" data-action="match-request" data-id="${id}">مطابقة المتبرعين</button><button class="btn btn-primary" data-action="fulfill-request" data-id="${id}">إكمال الطلب</button>`):'<button class="btn btn-secondary" data-action="close-modal">إغلاق</button>');}
  function bookModal(centerId='',requestId='',appointmentId=''){const a=state.appointments.find(a=>a.id===appointmentId);openModal(a?'تعديل موعد التبرع':'موعد صغير، أثر كبير',`<p class="modal-description">اختر المركز والوقت المناسبين لك. الحجز في هذه النسخة تجريبي.</p><form id="booking-form" data-form="booking"><input type="hidden" name="appointmentId" value="${escape(appointmentId)}"><input type="hidden" name="requestId" value="${escape(requestId||a?.requestId||'')}"><label class="field"><span class="field-label">مركز التبرع</span><select class="select" name="centerId" required>${state.centers.map(c=>`<option value="${c.id}" ${c.id===(a?.centerId||centerId)?'selected':''}>${escape(c.name)} — ${escape(c.city)}</option>`).join('')}</select></label><div class="form-grid">${field('تاريخ الموعد','date',a?.date||D.dateAfter(2),'date',`required min="${D.today()}" max="${D.dateAfter(60)}"`)}<label class="field"><span class="field-label">وقت الموعد</span><select class="select" name="time" required>${options(['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30','13:00'],a?.time||'10:00')}</select></label></div><label class="checkbox-row"><input type="checkbox" name="consent" required> أفهم أن هذا موعد تجريبي وأن المركز يحدد أهلية التبرع.</label>${daysRemaining()?`<p class="form-hint">المتبقي في عدّاد العرض: ${number(daysRemaining())} يومًا. هذا العدّاد ليس تقييمًا طبيًا.</p>`:''}</form>`,`<button class="btn btn-secondary" data-action="close-modal">إلغاء</button><button class="btn btn-primary" type="submit" form="booking-form">${icon('calendar')} ${a?'حفظ الموعد':'تأكيد الموعد'}</button>`);}
  function requestForm(id=''){if(state.role==='donor')return;const r=state.requests.find(r=>r.id===id);openModal(r?'تعديل طلب التبرع':'إنشاء طلب تبرع',`<form id="request-form" data-form="request"><input type="hidden" name="id" value="${escape(id)}"><label class="field"><span class="field-label">بنك الدم</span><select name="centerId" class="select" required>${state.centers.map(c=>`<option value="${c.id}" ${c.id===r?.centerId?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label><div class="form-grid"><label class="field"><span class="field-label">فصيلة الدم</span><select class="select" name="bloodType" required>${options(D.bloodTypes,r?.bloodType)}</select></label>${field('عدد الوحدات المطلوبة','units',r?.units||1,'number',`min="${r?.fulfilled||1}" max="100" required`)}<label class="field"><span class="field-label">الأولوية</span><select class="select" name="urgency">${[['normal','عادي'],['urgent','عاجل']].map(([v,t])=>`<option value="${v}" ${v===r?.urgency?'selected':''}>${t}</option>`).join('')}</select></label>${field('نطاق البحث (كم)','radius',r?.radius||15,'number','min="1" max="100" required')}</div><label class="field"><span class="field-label">ملاحظات الطلب</span><textarea class="textarea" name="note" maxlength="500" rows="3" placeholder="أضف معلومات تنظيمية للمتبرعين">${escape(r?.note||'')}</textarea></label><p class="form-hint">سيُحفظ الطلب محليًا. لا تُرسل هذه النسخة تنبيهات SMS أو رسائل خارج المتصفح.</p></form>`,`<button class="btn btn-secondary" data-action="close-modal">إلغاء</button><button class="btn btn-primary" type="submit" form="request-form">${r?'حفظ التعديلات':'نشر الطلب التجريبي'}</button>`);}
  function renderAuth(mode='login'){document.title='مرحبًا بك | حياة';$('#app').innerHTML=`<main class="auth-layout"><section class="auth-art">${logo()}<div><h1>العطاء نبضٌ،<br>وأنت <span>الحياة.</span></h1><p>نصل القلوب المستعدة للعطاء<br>بمن ينتظرون فرصة جديدة.</p>${heroArt()}</div><span>منصة حياة للتنسيق والتبرع بالدم · مشروع تخرج</span></section><section class="auth-panel"><span class="badge normal">نسخة تجريبية · فرونت إند</span><h2>${mode==='register'?'كن جزءًا من حياة':'أهلًا بعودتك'}</h2><p class="muted">${mode==='register'?'خطوتك الأولى نحو أثر لا يُنسى.':'ابدأ تجربة المنصة واختر الدور الذي تريد استكشافه.'}</p><div class="auth-tabs"><button class="auth-tab ${mode==='login'?'active':''}" data-action="auth-login">دخول تجريبي</button><button class="auth-tab ${mode==='register'?'active':''}" data-action="auth-register">إنشاء حساب تجريبي</button></div><form data-form="${mode}">${mode==='register'?`${field('الاسم الكامل','name','','text','required minlength="3" maxlength="70"')}${field('البريد الإلكتروني','email','','email','required')}${field('رقم الجوال','phone','','tel','required pattern="[+0-9 ()-]{7,20}"')}<div class="form-grid"><label class="field"><span class="field-label">فصيلة الدم</span><select class="select" name="bloodType" required>${options([...D.bloodTypes,'غير معروف'],'','اختر فصيلتك')}</select></label><label class="field"><span class="field-label">المدينة</span><select class="select" name="city" required>${options(D.cities,'','اختر مدينتك')}</select></label></div><label class="checkbox-row"><input type="checkbox" required> أوافق على حفظ بيانات العرض في هذا المتصفح.</label>`:`<label class="field"><span class="field-label">تجربة المنصة بصفة</span><select class="select" name="role"><option value="donor">متبرع</option><option value="bank">مسؤول بنك الدم</option><option value="admin">مدير النظام</option></select></label>`}<button class="btn btn-primary full-width" type="submit">${mode==='register'?'إنشاء الحساب':'ابدأ التجربة'} ${icon('arrow')}</button><p class="form-hint">لا تستخدم معلومات شخصية حقيقية. الدخول محاكاة محلية دون كلمة مرور أو اتصال بخادم.</p></form></section></main>`;}
  function csvDownload(filename,rows){const csv='\uFEFF'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  document.addEventListener('click',e=>{
    const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
    if(window.HayatAdmin?.action(action,el,ctx()))return;
    if(action==='close-modal'){closeModal();return;}
    if(action==='menu'){document.body.classList.toggle('menu-open');return;}if(action==='close-menu'){document.body.classList.remove('menu-open');return;}
    if(action==='open-login'||action==='open-register'){publicView=action==='open-login'?'login':'register';renderAuth(publicView);window.scrollTo(0,0);return;}
    if(action==='back-landing'){publicView='landing';renderLanding();window.scrollTo(0,0);return;}
    if(action==='auth-login'||action==='auth-register'){publicView=action==='auth-login'?'login':'register';renderAuth(publicView);return;}
    if(action==='logout'){state.signedIn=false;publicView='landing';save();closeModal();render();return;}
    if(!state.signedIn)return;
    if(action==='book'){bookModal(el.dataset.center);return;}
    if(action==='filter-status'){filters.status=el.dataset.value;render();return;}
    if(action==='request-detail'){requestDetail(id);return;}
    if(action==='reschedule'){bookModal('','',id);return;}
    if(action==='new-request'||action==='edit-request'){requestForm(id);return;}
    if(action==='match-request'&&state.role!=='donor'){state.matchRequestId=id;closeModal();navigate('donors');return;}
    if(action==='accept-request'||action==='decline-request'){
      const r=state.requests.find(r=>r.id===id);if(!r||r.status!=='open'||state.role!=='donor')return;
      if(action==='accept-request'&&!D.canDonate(state.profile.bloodType,r.bloodType)){toast(`فصيلة ${state.profile.bloodType} لا تتوافق مع طلب ${r.bloodType} للتبرع بخلايا الدم الحمراء. اختر طلبًا متوافقًا أو راجع بنك الدم.`,'error');return;}
      let response=state.responses.find(s=>s.requestId===id),next=action==='accept-request'?'accepted':'declined';
      if(!response){response={id:uid('res'),requestId:id,status:next,date:D.today()};state.responses.push(response);if(next==='accepted')r.responses++;}else{if(response.status!==next)r.responses=Math.max(0,r.responses+(next==='accepted'?1:-1));response.status=next;}
      save();closeModal();render();if(next==='accepted'){toast('تم تسجيل رغبتك بالتبرع. يمكنك الآن حجز موعد.');bookModal(r.centerId,r.id);}else toast('تم تسجيل اعتذارك. شكرًا لاهتمامك.');return;
    }
    if(action==='cancel-appointment'){confirmDialog('إلغاء موعد التبرع','هل تريد إلغاء هذا الموعد التجريبي؟ يمكنك حجز موعد آخر لاحقًا.','confirm-cancel-appointment',id,'إلغاء الموعد');return;}
    if(action==='confirm-cancel-appointment'){const a=state.appointments.find(a=>a.id===id);if(a)a.status='cancelled';save();closeModal();render();toast('تم إلغاء الموعد.');return;}
    if(action==='fulfill-request'||action==='cancel-request'){if(state.role==='donor')return;confirmDialog(action==='fulfill-request'?'إكمال الطلب':'إلغاء الطلب',action==='fulfill-request'?'تأكيد أن بنك الدم سجّل اكتمال الوحدات المطلوبة؟ قبول المتطوعين وحده لا يعني اكتمال التبرع.':'سيُغلق الطلب ولن يقبل استجابات جديدة.','confirm-'+action,id);return;}
    if(action==='confirm-fulfill-request'||action==='confirm-cancel-request'){if(state.role==='donor')return;const r=state.requests.find(r=>r.id===id);if(r){r.status=action==='confirm-fulfill-request'?'completed':'cancelled';if(r.status==='completed')r.fulfilled=r.units;}save();closeModal();render();toast('تم تحديث حالة الطلب.');return;}
    if(action==='complete-donation'){if(state.role==='donor')return;const a=state.appointments.find(a=>a.id===id);if(a?.date>D.today()){toast('يمكن تسجيل التبرع في يوم الموعد أو بعده.','error');return;}confirmDialog('تسجيل تبرع مكتمل','سيُضاف التبرع إلى السجل ويُحدّث آخر تاريخ تبرع في هذه التجربة.','confirm-complete-donation',id,'تسجيل التبرع');return;}
    if(action==='confirm-complete-donation'){if(state.role==='donor')return;const a=state.appointments.find(a=>a.id===id);if(!a||a.status!=='confirmed'||a.date>D.today())return;a.status='completed';state.history.unshift({id:uid('DON'),centerId:a.centerId,date:a.date,bloodType:state.profile.bloodType,status:'completed'});state.profile.lastDonation=a.date;const r=state.requests.find(r=>r.id===a.requestId);if(r&&r.status==='open'){r.fulfilled=Math.min(r.units,r.fulfilled+1);if(r.fulfilled===r.units)r.status='completed';}save();closeModal();render();toast('تم تسجيل التبرع وتحديث السجل.');return;}
    if(action==='join-campaign'){const c=state.campaigns.find(c=>c.id===id);if(!c)return;c.joined=!c.joined;c.enrolled+=c.joined?1:-1;save();render();toast(c.joined?'تم تسجيل مشاركتك التجريبية في الحملة.':'تم إلغاء المشاركة في الحملة.');return;}
    if(action==='center-detail'){const c=center(id);openModal(escape(c.name),`<div class="detail-list"><div class="detail-row"><span>المدينة</span><strong>${escape(c.city)}</strong></div><div class="detail-row"><span>العنوان</span><strong>${escape(c.address)}</strong></div><div class="detail-row"><span>ساعات العرض</span><strong>${escape(c.hours||'غير محدد')}</strong></div><div class="detail-row"><span>رقم تجريبي</span><strong dir="ltr">${escape(c.phone||'غير محدد')}</strong></div></div><p class="form-hint">هذه بيانات توضيحية، ولا تمثل تأكيدًا لموقع أو توفر المركز حاليًا.</p>`,`<button class="btn btn-primary" data-action="book" data-center="${escape(id)}">حجز موعد تجريبي</button>`);return;}
    if(action==='read-all'){state.notifications.forEach(n=>n.read=true);save();render();toast('تم تحديد جميع الإشعارات كمقروءة.');return;}
    if(action==='notification'){const n=state.notifications.find(n=>n.id===id);if(n){n.read=true;save();if(n.requestId){if(route==='requests'){render();requestDetail(n.requestId);}else{pendingRequestId=n.requestId;navigate('requests');}}else navigate(n.route||'notifications');}return;}
    if(action==='reset'){confirmDialog('إعادة ضبط التجربة','ستُحذف تغييرات هذه النسخة المحلية فقط وتعود بيانات العرض الأولية.','confirm-reset','','إعادة الضبط');return;}
    if(action==='confirm-reset'){state=D.seed();save();closeModal();navigate('dashboard');toast('تمت استعادة البيانات التجريبية.');return;}
    if(action==='export-history'){csvDownload('hayat-donation-history.csv',[['رقم التبرع','المركز','التاريخ','الفصيلة','الحالة'],...state.history.map(h=>[h.id,center(h.centerId).name,h.date,h.bloodType,'مكتمل'])]);toast('تم تجهيز سجل التبرعات للتنزيل.');}
  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!form.matches('[data-form]'))return;e.preventDefault();if(!form.reportValidity())return;if(window.HayatAdmin?.submit(form,ctx()))return;
    const values=Object.fromEntries(new FormData(form)),kind=form.dataset.form;
    if(kind==='search'){filters.query=String(values.query).trim();filters.status='all';navigate('requests');return;}
    if(kind==='login'){state.role=['donor','bank','admin'].includes(values.role)?values.role:'donor';state.signedIn=true;save();navigate('dashboard');render();return;}
    if(kind==='register'){if(!values.name.trim()){toast('أدخل اسمًا صحيحًا.','error');return;}state.profile={...state.profile,name:values.name.trim(),email:values.email.trim(),phone:values.phone,bloodType:values.bloodType,city:values.city,lastDonation:'',birthDate:''};state.history=[];state.appointments=[];state.responses=[];state.notifications=[];state.campaigns.forEach(c=>{if(c.joined)c.enrolled--;c.joined=false;});state.role='donor';state.signedIn=true;state.donors[0]={...state.donors[0],...state.profile,id:'d1',status:'active'};save();navigate('dashboard');render();toast('أهلًا بك في حياة. تم إنشاء حسابك التجريبي.');return;}
    if(!state.signedIn)return;
    if(kind==='profile'){if(!values.name.trim()){toast('أدخل اسمًا صحيحًا.','error');return;}Object.assign(state.profile,values,{name:values.name.trim(),available:!!values.available,reminders:!!values.reminders,emergencyAlerts:!!values.emergencyAlerts});const donor=state.donors.find(d=>d.id==='d1');if(donor)Object.assign(donor,state.profile);save();render();toast('تم حفظ معلوماتك وتفضيلاتك.');return;}
    if(kind==='booking'){
      if(values.date<D.today()||values.date>D.dateAfter(60)||!state.centers.some(c=>c.id===values.centerId)){toast('اختر مركزًا وتاريخًا صالحين خلال ٦٠ يومًا.','error');return;}
      if(values.date===D.today()&&new Date(`${values.date}T${values.time}:00`)<=new Date()){toast('هذا الوقت مضى؛ اختر وقتًا لاحقًا.','error');return;}
      if(state.appointments.some(a=>a.status==='confirmed'&&a.id!==values.appointmentId&&a.date===values.date)){toast('لديك موعد في هذا اليوم. يمكنك تعديله من صفحة مواعيدي.','error');return;}
      let a=state.appointments.find(a=>a.id===values.appointmentId);if(a&&a.status!=='confirmed'){toast('لا يمكن تعديل موعد مغلق.','error');return;}if(a)Object.assign(a,{centerId:values.centerId,date:values.date,time:values.time});else{a={id:uid('APT'),centerId:values.centerId,date:values.date,time:values.time,requestId:values.requestId||null,status:'confirmed'};state.appointments.unshift(a);}
      if(state.profile.reminders)notify('تم تأكيد موعدك التجريبي',`${center(a.centerId).name}، ${formatDate(a.date)} الساعة ${a.time}.`,'appointments');save();closeModal();render();openModal('خطوتك القادمة تصنع فرقًا',`<div class="success-state"><span class="success-icon">${icon('check')}</span><h3>تم تأكيد موعدك التجريبي!</h3><p>${escape(center(a.centerId).name)}</p><div class="appointment-summary">${icon('calendar')} ${formatDate(a.date)} <span>·</span> <bdi>${a.time}</bdi></div><p class="form-hint">حُفظ الموعد في متصفحك فقط ولم يُرسل إلى مركز فعلي.</p></div>`,`<button class="btn btn-primary" data-action="close-modal">تم، شكرًا</button><a href="#appointments" class="btn btn-secondary" data-action="close-modal">عرض مواعيدي</a>`);return;
    }
    if(kind==='request'){
      if(state.role==='donor')return;const c=center(values.centerId),r=state.requests.find(r=>r.id===values.id);if(!state.centers.some(c=>c.id===values.centerId)||!D.bloodTypes.includes(values.bloodType)||Number(values.units)<Math.max(1,r?.fulfilled||0))return;
      const fields={centerId:values.centerId,hospital:c.name,city:c.city,bloodType:values.bloodType,units:Number(values.units),urgency:values.urgency,radius:Number(values.radius),note:values.note.trim()};if(r)Object.assign(r,fields);else{const next={...fields,id:uid('REQ'),fulfilled:0,responses:0,created:D.today(),status:'open'};state.requests.unshift(next);if(state.profile.available&&state.profile.emergencyAlerts&&D.canDonate(state.profile.bloodType,next.bloodType)&&next.city===state.profile.city)notify('طلب جديد يناسب فصيلتك',`${next.hospital} يحتاج فصيلة ${next.bloodType} المتوافقة مع تبرعك.`,'requests');}save();closeModal();render();toast(r?'تم تحديث الطلب.':'تم نشر الطلب في النسخة التجريبية.');
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='request-search'){filters.query=e.target.value;$('#request-results').innerHTML=filteredRequests();}});
  document.addEventListener('change',e=>{if(e.target.id==='blood-filter'||e.target.id==='city-filter'){filters[e.target.id==='blood-filter'?'blood':'city']=e.target.value;$('#request-results').innerHTML=filteredRequests();}if(e.target.id==='role-selector'){state.role=e.target.value;save();closeModal();navigate('dashboard');toast('تم تبديل الدور التجريبي.');}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.body.classList.remove('menu-open');}if(e.key==='Tab'&&$('.modal')){const focusable=[...$('.modal').querySelectorAll('button,a[href],input:not([type=hidden]),select,textarea')].filter(el=>!el.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
  window.addEventListener('hashchange',()=>{closeModal();route=location.hash.slice(1)||'dashboard';if(!state.signedIn&&publicView==='landing'&&['top','how','impact','about'].includes(route))return;render();window.scrollTo(0,0);if(pendingRequestId){const id=pendingRequestId;pendingRequestId=null;requestDetail(id);}});
  window.addEventListener('offline',()=>toast('أنت غير متصل؛ يمكنك متابعة استخدام البيانات المحلية.'));
  render();if(!storageAvailable)toast('المتصفح لا يتيح التخزين المحلي؛ تغييراتك مؤقتة لهذه الجلسة.','error');
  if('serviceWorker' in navigator&&['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();

